static NSDictionary *props(NSSearchField *s,NSString *stage){NSSearchFieldCell *c=(NSSearchFieldCell *)s.cell;return @{@"stage":stage,@"viewClass":NSStringFromClass(s.class),@"cellClass":NSStringFromClass(c.class),@"scrollable":@(c.scrollable),@"usesSingleLineMode":@(c.usesSingleLineMode),@"wraps":@(c.wraps),@"lineBreakMode":@(c.lineBreakMode),@"bezeled":@(s.bezeled),@"bordered":@(s.bordered),@"searchTextBounds":NSStringFromRect(s.searchTextBounds)};}
int main(){@autoreleasepool{[NSApplication sharedApplication];NSMutableArray *a=[NSMutableArray new];for(Class cls in @[NSSearchField.class,NotesUISearchField.class]){NSSearchField *s=[[cls alloc]initWithFrame:NSZeroRect];[a addObject:props(s,@"initial")];s.formatter=[NotesUISearchFormatter new];s.placeholderString=@"搜索";s.sendsSearchStringImmediately=YES;s.sendsWholeSearchString=NO;s.recentsAutosaveName=nil;s.maximumRecents=0;s.searchMenuTemplate=nil;s.bordered=NO;s.bezeled=NO;s.drawsBackground=NO;s.frame=NSMakeRect(0,0,178,28);[a addObject:props(s,@"production-equivalent-no-window")];}NSData *d=[NSJSONSerialization dataWithJSONObject:a options:NSJSONWritingPrettyPrinted error:nil];fwrite(d.bytes,1,d.length,stdout);fputc('\n',stdout);}}
